svg.script:
//
(function(){
  var sc=document.getElementById('city-zoom');
  var svg=(sc&&sc.ownerSVGElement)||document.documentElement;
  if(!svg||!svg.querySelectorAll)return;
  var cities=svg.querySelectorAll('#cities .city');
  var lvl2=svg.querySelectorAll('#cities .lvl2'),lvl3=svg.querySelectorAll('#cities .lvl3');
  var layer=svg.querySelector('#cities');
  var base=null,last=-1;
  function show(list,on){for(var i=0;i<list.length;i++)list[i].setAttribute('display',on?'inline':'none');}
  function check(){
    var ref=(layer&&layer.getScreenCTM)?layer:svg;
    var ctm=ref.getScreenCTM&&ref.getScreenCTM();
    if(!ctm)return;
    var s=Math.sqrt(Math.abs(ctm.a*ctm.d-ctm.b*ctm.c))*(window.devicePixelRatio||1);
    if(base===null&&s>0)base=s;
    if(!base)return;
    var z=s/base;
    if(Math.abs(z-last)<=0.001)return;
    last=z;
    var lvl=z>=2.6?3:(z>=1.5?2:1);
    svg.setAttribute('data-city-zoom',String(lvl));
    show(lvl2,lvl>=2);show(lvl3,lvl>=3);
    var k=Math.max(1/Math.max(z,1),0.12);
    for(var i=0;i<cities.length;i++){
      var c=cities[i];
      c.setAttribute('transform','translate('+c.getAttribute('data-x')+' '+c.getAttribute('data-y')+') scale('+k+')');
    }
  }
  check();
  window.setInterval(check,250);
  window.addEventListener('resize',check);
  window.addEventListener('wheel',check,true);
})();
//
